@Composable
fun NetMasterApp(vm:NetMasterViewModel){
    var tab by remember{mutableIntStateOf(0)};var selectedLevel by remember{mutableStateOf<Int?>(null)};var selectedLesson by remember{mutableStateOf<Lesson?>(null)};var searchOpen by remember{mutableStateOf(false)}
    val tabs=listOf("خانه" to Icons.Default.Home,"یادگیری" to Icons.Default.MenuBook,"Lab" to Icons.Default.Build,"آزمون" to Icons.Default.Quiz,"یادداشت" to Icons.Default.EditNote,"AI" to Icons.Default.AutoAwesome,"Ops" to Icons.Default.Dns,"Simulator" to Icons.Default.Terminal,"Engineer OS" to Icons.Default.Hub)
    Scaffold(topBar={if(selectedLesson==null&&selectedLevel==null&&!searchOpen)TopAppBar(title={Text("NetMaster",fontWeight=FontWeight.Bold)},actions={IconButton({searchOpen=true}){Icon(Icons.Default.Search,"جستجو")}})},bottomBar={NavigationBar{tabs.forEachIndexed{i,x->NavigationBarItem(i==tab,{tab=i;selectedLevel=null;selectedLesson=null;searchOpen=false},{Icon(x.second,x.first)},label={Text(x.first,fontSize=10.sp)})}}}){pad->Box(Modifier.padding(pad).fillMaxSize()){when{searchOpen->Search(vm){selectedLesson=it;searchOpen=false};selectedLesson!=null->LessonScreen(selectedLesson!!,vm){selectedLesson=null};selectedLevel!=null->LevelScreen(vm,selectedLevel!!){selectedLesson=it};tab==0->Dashboard(vm){tab=1};tab==1->Learning(vm){selectedLevel=it};tab==2->Labs(vm);tab==3->Quiz(vm){selectedLesson=it};tab==4->Notes(vm);tab==5->AICenter(vm);tab==6->OperationsCenter(vm);tab==7->SimulatorCenter(vm);tab==8->V11EngineerOS(vm);else->Dashboard(vm){tab=0}}}}}
}

@Composable fun Dashboard(vm:NetMasterViewModel,openLearning:()->Unit){
    val c=vm.curriculum.collectAsState().value?:return;val p=vm.progress.collectAsState().value;val total=c.levels.sumOf{it.lessons.size};val done=p.values.count{it.completed};val mastered=p.values.count{it.mastery==Mastery.MASTERED.name};val deep=vm.deepLessonCount.collectAsState().value;val scenarios=vm.scenarioCount.collectAsState().value
    LazyColumn(Modifier.padding(16.dp),verticalArrangement=Arrangement.spacedBy(12.dp)){
        item{Text("NetMaster — مرکز مهندسی IT و شبکه",style=MaterialTheme.typography.headlineSmall,fontWeight=FontWeight.Bold);Text("Offline-first • Learning • Labs • RAG • AI • Evidence Correlation • Digital Twin • Operations")}
        item{Row(horizontalArrangement=Arrangement.spacedBy(8.dp),modifier=Modifier.fillMaxWidth()){Box(Modifier.weight(1f)){MetricCard("درس",done.toString()+" / "+total,if(total==0)0f else done.toFloat()/total)};Box(Modifier.weight(1f)){MetricCard("مسلط",mastered.toString(),if(total==0)0f else mastered.toFloat()/total)}}}
        item{Card(onClick=openLearning){Column(Modifier.padding(16.dp)){Text("مسیر حرفه‌ای",style=MaterialTheme.typography.titleLarge,fontWeight=FontWeight.Bold);Text("${c.levels.size} سطح یکپارچه • ${vm.catalogCount.collectAsState().value} رکورد قابل جست‌وجو");Text("Concept → Packet/State → Config → Verification → Troubleshooting → Lab → Project")}}}
        item{Card{Column(Modifier.padding(16.dp)){Text("Unified Engineering Pack",style=MaterialTheme.typography.titleLarge,fontWeight=FontWeight.Bold);Text("$deep درس عمیق • $scenarios سناریوی Break/Fix • ${vm.labCatalog.collectAsState().value?.labs?.size ?: 0} Lab");Text("Ethernet • VLAN • STP • Routing • OSPF/BGP • DNS/AD • MikroTik • Cisco • Linux • VMware • Zabbix • Wireshark • Wazuh • Cloud")}}}
        item{AboutCreatorCard()}
        item{Text("شروع سریع",style=MaterialTheme.typography.titleLarge,fontWeight=FontWeight.Bold)}
        items(c.levels.take(12)){l->Card{Column(Modifier.padding(12.dp)){Text("${l.id}. ${l.title}",fontWeight=FontWeight.Bold);Text("${l.lessons.size} درس")}}}
    }
}
