@Composable fun Labs(vm:NetMasterViewModel){val twin=vm.twin.collectAsState().value;val faults=vm.twinEngine.faults();LazyColumn(Modifier.padding(16.dp),verticalArrangement=Arrangement.spacedBy(10.dp)){item{Text("Digital Twin Lab",style=MaterialTheme.typography.headlineSmall,fontWeight=FontWeight.Bold);Text("Fault Injection + Evidence + Simulator State")};item{TwinGraph(twin.nodes,twin.links,Modifier.fillMaxWidth().height(250.dp))};item{Row(horizontalArrangement=Arrangement.spacedBy(8.dp)){Button({vm.resetTwin()}){Text("Reset Twin")};Button({vm.saveSimulatorSnapshot("manual")}){Text("Snapshot")}}};item{Card{Column(Modifier.padding(14.dp)){Text("State",fontWeight=FontWeight.Bold);twin.simulator?.let{s->Text("VLANs: ${s.vlans.sorted().joinToString()}");Text("Routes: ${s.routes.size} • ARP: ${s.arp.size}");Text("DNS ${if(s.dnsHealthy)"OK" else "FAIL"} • Firewall ${if(s.firewallHealthy)"OK" else "FAIL"} • NAT ${if(s.natHealthy)"OK" else "FAIL"}");Text("OSPF ${if(s.ospfHealthy)"UP" else "DEGRADED"} • BGP ${if(s.bgpHealthy)"UP" else "DOWN"} • QoS ${if(s.qosHealthy)"OK" else "CONGESTED"}")}}}};item{Text("Fault Injection",style=MaterialTheme.typography.titleLarge,fontWeight=FontWeight.Bold)};items(faults){f->Card(onClick={vm.injectFault(f)}){Column(Modifier.padding(14.dp)){Text(f.title,fontWeight=FontWeight.Bold);Text(f.description);Text("Severity: ${f.severity} • Target: ${f.target}")}}};twin.activeFault?.let{f->item{Card{Column(Modifier.padding(14.dp),verticalArrangement=Arrangement.spacedBy(6.dp)){Text("Fault فعال: ${f.title}",fontWeight=FontWeight.Bold);Text("Hint: ${f.hint}");Button({vm.recordEvidence("بررسی ${f.target}")}){Text("ثبت Evidence")};Text("Evidence: ${twin.evidence.joinToString()}");Text("Score: ${twin.score}")}}}}}}

@Composable fun TwinGraph(nodes:List<TwinNode>,links:List<TwinLink>,modifier:Modifier){Canvas(modifier.background(MaterialTheme.colorScheme.surfaceVariant)){if(nodes.isEmpty())return@Canvas;val center=Offset(size.width/2,size.height/2);val radius=minOf(size.width,size.height)*0.34f;val pos=nodes.mapIndexed{idx,n->n.id to Offset(center.x+radius*cos(idx*2.0*Math.PI/nodes.size).toFloat(),center.y+radius*sin(idx*2.0*Math.PI/nodes.size).toFloat())}.toMap();links.forEach{e->pos[e.from]?.let{a->pos[e.to]?.let{b->drawLine(MaterialTheme.colorScheme.outline,a,b,3f)}}};nodes.forEach{n->val p=pos[n.id]?:center;drawCircle(MaterialTheme.colorScheme.primary,18f,p);drawContext.canvas.nativeCanvas.drawText(n.name,p.x-48,p.y-25,android.graphics.Paint().apply{color=android.graphics.Color.DKGRAY;textSize=20f})}}}

