fun masteryLabel(v:String)=when(v){Mastery.UNKNOWN.name->"بلد نیستم";Mastery.REVIEW.name->"نیاز به مرور";Mastery.KNOWN.name->"بلدم";Mastery.MASTERED.name->"مسلط هستم";else->v}

