        item{Card{Column(Modifier.padding(14.dp),verticalArrangement=Arrangement.spacedBy(6.dp)){Text("Wireshark-like Filter",fontWeight=FontWeight.Bold);OutlinedTextField(filter,{filter=it},Modifier.fillMaxWidth(),label={Text("tcp and tcp.port == 443")});Row(horizontalArrangement=Arrangement.spacedBy(8.dp)){Button({vm.filterCapture(filter)}){Text("Filter")};OutlinedButton({vm.resetPacketFilter();filter=""}){Text("Reset")}};filterError?.let{Text("Filter error: $it")};packets.take(30).forEach{p->Text("#${p.number} ${p.source} → ${p.destination} ${p.protocol} ${p.srcPort?:""}:${p.dstPort?:""} ${p.tcpFlags} ${p.info}",fontFamily=FontFamily.Monospace,fontSize=10.sp)}}}}
        item{Card{Column(Modifier.padding(14.dp),verticalArrangement=Arrangement.spacedBy(6.dp)){Text("Config Snapshots + Diff",fontWeight=FontWeight.Bold);OutlinedTextField(device,{device=it},Modifier.fillMaxWidth(),label={Text("Device ID")});OutlinedTextField(vendor,{vendor=it},Modifier.fillMaxWidth(),label={Text("Vendor")});OutlinedTextField(label,{label=it},Modifier.fillMaxWidth(),label={Text("Snapshot label")});OutlinedTextField(cfgText,{cfgText=it},Modifier.fillMaxWidth(),minLines=3,label={Text("Configuration snapshot")});Button({if(device.isNotBlank()&&cfgText.isNotBlank())vm.saveConfig(device,vendor,label.ifBlank{"snapshot"},cfgText)},Modifier.fillMaxWidth()){Text("ذخیره Snapshot")};Row(horizontalArrangement=Arrangement.spacedBy(6.dp)){OutlinedTextField(oldCfg,{oldCfg=it},Modifier.weight(1f),minLines=3,label={Text("Old")});OutlinedTextField(newCfg,{newCfg=it},Modifier.weight(1f),minLines=3,label={Text("New")})};Button({diff=vm.configDiffEngine.diff(oldCfg,newCfg)},Modifier.fillMaxWidth()){Text("Diff")};diff.take(50).forEach{Text("${it.type} ${it.lineNumber}: ${it.line}",fontFamily=FontFamily.Monospace)};configs.take(5).forEach{Text("#${it.id} ${it.deviceId} • ${it.vendor} • ${it.label} • ${it.fingerprint}")}}}}
        item{Card{Column(Modifier.padding(14.dp),verticalArrangement=Arrangement.spacedBy(6.dp)){Text("Knowledge Graph",fontWeight=FontWeight.Bold);Text("Nodes: ${kg.nodes.size} • Edges: ${kg.edges.size}");Button({vm.buildKnowledgeGraph()},Modifier.fillMaxWidth()){Text("Build / Update Graph")};if(kg.nodes.isNotEmpty())GraphView(kg)}}}
    }
}

@Composable fun GraphView(kg:KnowledgeGraphView){Canvas(Modifier.fillMaxWidth().height(320.dp).background(MaterialTheme.colorScheme.surfaceVariant)){val nodes=kg.nodes.take(90);if(nodes.isEmpty())return@Canvas;val center=Offset(size.width/2,size.height/2);val radius=minOf(size.width,size.height)*0.36f;val pos=nodes.mapIndexed{idx,n->n.id to Offset(center.x+radius*cos(idx*2.0*Math.PI/nodes.size).toFloat(),center.y+radius*sin(idx*2.0*Math.PI/nodes.size).toFloat())}.toMap();kg.edges.filter{pos.containsKey(it.fromId)&&pos.containsKey(it.toId)}.take(240).forEach{e->drawLine(MaterialTheme.colorScheme.outline,pos[e.fromId]!!,pos[e.toId]!!,2f)};nodes.forEach{n->val p=pos[n.id]!!;drawCircle(if(n.kind=="TAG")MaterialTheme.colorScheme.secondary else MaterialTheme.colorScheme.primary,10f,p)}}}

@Composable fun IncidentWorkspaceScreen(ws:IncidentWorkspace,root:String,onRoot:(String)->Unit,resolution:String,onResolution:(String)->Unit,onResolve:()->Unit,onInvestigate:()->Unit,onBack:()->Unit,onEvidence:(Pair<String,String>)->Unit){var evidence by remember{mutableStateOf("")};LazyColumn(Modifier.padding(16.dp),verticalArrangement=Arrangement.spacedBy(10.dp)){item{Row(Modifier.fillMaxWidth(),horizontalArrangement=Arrangement.SpaceBetween){Text("Incident #${ws.incident.id}",style=MaterialTheme.typography.headlineSmall,fontWeight=FontWeight.Bold);TextButton(onBack){Text("بازگشت")}};Text(ws.incident.title);Text("${ws.incident.status} • ${ws.incident.severity}")};item{section("Symptom",ws.incident.symptom)};item{Text("Evidence Timeline",style=MaterialTheme.typography.titleLarge,fontWeight=FontWeight.Bold);ws.evidence.forEach{Card{Text("${it.type}: ${it.value}",Modifier.padding(12.dp))}};ws.events.forEach{Card{Text("${it.eventType} • ${it.message}",Modifier.padding(10.dp))}}};item{Text("Linked Captures",style=MaterialTheme.typography.titleLarge,fontWeight=FontWeight.Bold);ws.linkedCaptures.forEach{Text("#${it.id} ${it.name} • ${it.packetCount} packets • ${it.protocolSummary}")}};item{Text("Linked Configs",style=MaterialTheme.typography.titleLarge,fontWeight=FontWeight.Bold);ws.linkedConfigs.forEach{Text("#${it.id} ${it.deviceId} • ${it.vendor} • ${it.label}")}};item{OutlinedTextField(evidence,{evidence=it},Modifier.fillMaxWidth(),label={Text("Evidence جدید")});Button({if(evidence.isNotBlank()){onEvidence("NOTE" to evidence);evidence=""}},Modifier.fillMaxWidth()){Text("ثبت Evidence")}};item{OutlinedTextField(root,onRoot,Modifier.fillMaxWidth(),label={Text("Root Cause")});OutlinedTextField(resolution,onResolution,Modifier.fillMaxWidth(),minLines=3,label={Text("Resolution")});Row(horizontalArrangement=Arrangement.spacedBy(8.dp)){Button(onInvestigate){Text("Investigate")};Button(onResolve){Text("Resolve")}}}}

@Composable fun SimulatorCenter(vm:NetMasterViewModel){val twin=vm.twin.collectAsState().value;val coach=vm.coach.collectAsState().value;val output=vm.simOutput.collectAsState().value;var command by remember{mutableStateOf("")};var symptom by remember{mutableStateOf("")};LazyColumn(Modifier.padding(16.dp),verticalArrangement=Arrangement.spacedBy(10.dp)){item{Text("Network Command Simulator",style=MaterialTheme.typography.headlineSmall,fontWeight=FontWeight.Bold);Text("Safe sandbox — هیچ Commandای روی تجهیزات واقعی اجرا نمی‌شود.")};item{TwinGraph(twin.nodes,twin.links,Modifier.fillMaxWidth().height(250.dp))};item{Card{Column(Modifier.padding(14.dp),verticalArrangement=Arrangement.spacedBy(6.dp)){Text("Simulator State",fontWeight=FontWeight.Bold);twin.simulator?.let{s->Text("VLAN ${s.vlans.sorted().joinToString()} • Routes ${s.routes.size} • ARP ${s.arp.size}");Text("DNS=${s.dnsHealthy} NAT=${s.natHealthy} FW=${s.firewallHealthy} OSPF=${s.ospfHealthy} BGP=${s.bgpHealthy} STP=${s.stpHealthy} QoS=${s.qosHealthy}")};OutlinedTextField(command,{command=it},Modifier.fillMaxWidth(),label={Text("show ip route / show vlan / ping / nslookup / disable dns")});Button({vm.runSimulator(command)},Modifier.fillMaxWidth()){Text("Execute in Simulator")};Row(horizontalArrangement=Arrangement.spacedBy(8.dp)){OutlinedButton({vm.saveSimulatorSnapshot("manual")}){Text("Snapshot")};OutlinedButton({vm.resetTwin()}){Text("Reset")}};if(output.isNotBlank())Text(output,fontFamily=FontFamily.Monospace)}}};item{Card{Column(Modifier.padding(14.dp),verticalArrangement=Arrangement.spacedBy(6.dp)){Text("AI Autonomous Troubleshooting Coach",fontWeight=FontWeight.Bold);OutlinedTextField(symptom,{symptom=it},Modifier.fillMaxWidth(),minLines=2,label={Text("Symptom")});Row(horizontalArrangement=Arrangement.spacedBy(8.dp)){Button({vm.startCoach(symptom)}){Text("Start Coach")};OutlinedButton({vm.coachNext()}){Text("Next Test")}};coach?.let{c->Text("${c.status} • Scenario=${c.scenarioId?:"generic"}");Text("Step ${minOf(c.currentIndex+1,c.steps.size)} / ${c.steps.size}",fontWeight=FontWeight.Bold);c.steps.getOrNull(c.currentIndex)?.let{s->Text("${s.title}\n${s.reason}\nCommand: ${s.command}\nExpected: ${s.expected}")};if(c.evidence.isNotEmpty())Text("Evidence:\n${c.evidence.takeLast(8).joinToString("\n")}");if(c.findings.isNotEmpty())Text("Findings: ${c.findings.joinToString(" | ")}")}}}};item{Text("Model: Evidence → Hypothesis → Test → Result → Finding → Human Validation → Fix/Rollback")}}
}

@Composable
fun V11EngineerOS(vm:NetMasterViewModel){
    val investigation=vm.v11Investigation.collectAsState().value
    val passport=vm.v11Passport.collectAsState().value
    val selectedFault=vm.v11SelectedFault.collectAsState().value
    val faults=vm.v11Faults.collectAsState().value
    var symptom by remember{mutableStateOf("")}
    var evidence by remember{mutableStateOf("")}
    var activeFault by remember{mutableStateOf<String?>(null)}
    LaunchedEffect(Unit){vm.computeV11Passport()}
    LazyColumn(Modifier.padding(16.dp),verticalArrangement=Arrangement.spacedBy(12.dp)){
        item{Text("NetMaster V11 — Digital Network Engineer",style=MaterialTheme.typography.headlineSmall,fontWeight=FontWeight.Bold);Text("Evidence → Causality → First Divergence → Test → Root Cause → Verification")}
        item{Card{Column(Modifier.padding(14.dp),verticalArrangement=Arrangement.spacedBy(8.dp)){Text("Engineering Evidence Chain",fontWeight=FontWeight.Bold);Text("هر نتیجه باید به Evidence قابل ردیابی و یک Test قابل رد/تأیید متصل باشد.");OutlinedTextField(symptom,{symptom=it},Modifier.fillMaxWidth(),label={Text("Symptom")});OutlinedTextField(evidence,{evidence=it},Modifier.fillMaxWidth(),minLines=5,label={Text("Packet / Log / Config / Metric / Observation")});Row(horizontalArrangement=Arrangement.spacedBy(8.dp)){Button({if(symptom.isNotBlank())vm.investigateV11(symptom,evidence)}){Text("Investigate")};OutlinedButton({symptom="";evidence="";vm.clearV11()}){Text("Reset")}}}}
        investigation?.let{inv->
            item{Card{Column(Modifier.padding(14.dp),verticalArrangement=Arrangement.spacedBy(7.dp)){Text("First Divergence",fontWeight=FontWeight.Bold);Text(inv.firstDivergence);Text("Causal Chain",style=MaterialTheme.typography.titleMedium,fontWeight=FontWeight.Bold);inv.causalChain.forEach{Text("${it.from}  —${it.relation}→  ${it.to}");Text("Evidence: ${it.evidence}",style=MaterialTheme.typography.bodySmall)} }}}
            item{Text("Hypotheses",style=MaterialTheme.typography.titleLarge,fontWeight=FontWeight.Bold)}
            items(inv.hypotheses){h->Card{Column(Modifier.padding(12.dp)){Row(Modifier.fillMaxWidth(),horizontalArrangement=Arrangement.SpaceBetween){Text(h.title,fontWeight=FontWeight.Bold);Text("${h.confidence}%")};h.basis.forEach{Text("• $it")};Text("Falsifier: ${h.falsifier}",style=MaterialTheme.typography.bodySmall);Text("Next test: ${h.nextTest}",style=MaterialTheme.typography.bodySmall)}}}
            if(inv.blastRadius.isNotEmpty())item{Card{Column(Modifier.padding(14.dp)){Text("Dependency Blast Radius",style=MaterialTheme.typography.titleMedium,fontWeight=FontWeight.Bold);inv.blastRadius.forEach{Text("${it.node} • ${it.relation} • impact ${it.impact}%");Text(it.why,style=MaterialTheme.typography.bodySmall)}}}}
            if(inv.relatedLessons.isNotEmpty())item{Card{Column(Modifier.padding(14.dp)){Text("Related Knowledge",fontWeight=FontWeight.Bold);inv.relatedLessons.forEach{Text("• $it")}}}}
        }
        item{Card{Column(Modifier.padding(14.dp),verticalArrangement=Arrangement.spacedBy(7.dp)){Text("Engineering Passport",style=MaterialTheme.typography.titleLarge,fontWeight=FontWeight.Bold);if(passport!=null){Text("Overall Engineering Score: ${passport.overall}%",fontWeight=FontWeight.Bold);passport.competencies.forEach{Text("${it.name}: ${it.score}%");Text("Evidence: ${it.evidence}",style=MaterialTheme.typography.bodySmall)};Text("Strengths: ${passport.strengths.joinToString("، ")}");Text("Gaps to train: ${passport.gaps.joinToString("، ")}")}else Text("در حال محاسبه...")}}}
        item{Card{Column(Modifier.padding(14.dp)){Text("Controlled Failure Injection",style=MaterialTheme.typography.titleLarge,fontWeight=FontWeight.Bold);Text("خرابی کنترل‌شده برای Lab؛ فقط Twin داخلی تغییر می‌کند.");faults.forEach{f->Row(Modifier.fillMaxWidth().padding(vertical=4.dp),horizontalArrangement=Arrangement.SpaceBetween){Column(Modifier.weight(1f)){Text(f.title,fontWeight=FontWeight.Bold);Text("${f.layer} • ${f.firstDivergence}",style=MaterialTheme.typography.bodySmall)};Button({activeFault=f.id;vm.injectV11Fault(f.id)}){Text(if(activeFault==f.id)"Injected" else "Inject")}}}}}}
        selectedFault?.let{f->item{Card{Column(Modifier.padding(14.dp),verticalArrangement=Arrangement.spacedBy(5.dp)){Text("Active Fault: ${f.title}",fontWeight=FontWeight.Bold);Text("Symptom: ${f.symptom}");Text("Expected Evidence",fontWeight=FontWeight.Bold);f.expectedEvidence.forEach{x->Text("• $x")};Text("First Divergence: ${f.firstDivergence}");Text("Remediation: ${f.remediation}");Text("Rollback: ${f.rollback}")}}}}
    }
}
